\\
\displaystyle F_{\text{between blocks}}=\frac{MSB}{MSE}
\\
\displaystyle MST=\frac{\displaystyle b\sum_{i=1}^k(\bar{Y}_{i.}-\bar{Y}_{..})^2}{k-1}
\\
\displaystyle MSB=\frac{\displaystyle k\sum_{j=1}^b(\bar{Y}_{.j}-\bar{Y}_{..})^2}{b-1}
\\
\displaystyle MSE=\frac{\displaystyle \sum_{i=1}^k \sum_{j=1}^b (Y_{ij}-\bar{Y}_{i.}-\bar{Y}_{.j}+\bar{Y}_{..})^2} {(k-1)(b-1)}$Z
